ALTER TABLE seasons ADD COLUMN lobby_rules_profile VARCHAR(16) NOT NULL DEFAULT 'LEGACY';
ALTER TABLE seasons ADD CONSTRAINT ck_season_lobby_profile CHECK (CASE lobby_rules_profile WHEN 'LEGACY' THEN 1 WHEN 'CTC_2027' THEN 1 ELSE 0 END = 1);
ALTER TABLE race_settings ADD COLUMN start_type VARCHAR(24) NOT NULL DEFAULT 'GRID_FALSE_START';
ALTER TABLE race_settings ADD COLUMN slipstream VARCHAR(16) NOT NULL DEFAULT 'REAL';
ALTER TABLE race_settings ADD CONSTRAINT ck_race_start_type CHECK (CASE start_type WHEN 'GRID_FALSE_START' THEN 1 WHEN 'ROLLING' THEN 1 ELSE 0 END = 1);
ALTER TABLE race_settings ADD CONSTRAINT ck_race_slipstream CHECK (CASE slipstream WHEN 'REAL' THEN 1 WHEN 'WEAK' THEN 1 ELSE 0 END = 1);
ALTER TABLE matchday_pick_revisions ADD COLUMN lobby_rules_profile VARCHAR(16) NOT NULL DEFAULT 'LEGACY';
ALTER TABLE matchday_pick_revisions ADD COLUMN start_type VARCHAR(24) NOT NULL DEFAULT 'GRID_FALSE_START';
ALTER TABLE matchday_pick_revisions ADD COLUMN slipstream VARCHAR(16) NOT NULL DEFAULT 'REAL';
ALTER TABLE matchday_pick_revisions ADD CONSTRAINT ck_revision_lobby_choices CHECK ((lobby_rules_profile = 'LEGACY' AND start_type = 'GRID_FALSE_START' AND slipstream = 'REAL') OR (lobby_rules_profile = 'CTC_2027' AND CASE start_type WHEN 'GRID_FALSE_START' THEN 1 WHEN 'ROLLING' THEN 1 ELSE 0 END = 1 AND CASE slipstream WHEN 'REAL' THEN 1 WHEN 'WEAK' THEN 1 ELSE 0 END = 1));
ALTER TABLE pick_publication_attempts ADD COLUMN lobby_rules_profile VARCHAR(16) NOT NULL DEFAULT 'LEGACY';
ALTER TABLE pick_publication_attempts ADD COLUMN start_type VARCHAR(24) NOT NULL DEFAULT 'GRID_FALSE_START';
ALTER TABLE pick_publication_attempts ADD COLUMN slipstream VARCHAR(16) NOT NULL DEFAULT 'REAL';
ALTER TABLE pick_publication_attempts ADD CONSTRAINT ck_publication_lobby_choices CHECK ((lobby_rules_profile = 'LEGACY' AND start_type = 'GRID_FALSE_START' AND slipstream = 'REAL') OR (lobby_rules_profile = 'CTC_2027' AND CASE start_type WHEN 'GRID_FALSE_START' THEN 1 WHEN 'ROLLING' THEN 1 ELSE 0 END = 1 AND CASE slipstream WHEN 'REAL' THEN 1 WHEN 'WEAK' THEN 1 ELSE 0 END = 1));
ALTER TABLE matchday_pick_decisions ADD COLUMN lobby_rules_profile VARCHAR(16);
ALTER TABLE matchday_pick_decisions ADD COLUMN start_type VARCHAR(24);
ALTER TABLE matchday_pick_decisions ADD COLUMN slipstream VARCHAR(16);
UPDATE matchday_pick_decisions SET lobby_rules_profile = 'LEGACY', start_type = 'GRID_FALSE_START', slipstream = 'REAL' WHERE car_id IS NOT NULL;
ALTER TABLE matchday_pick_decisions ADD CONSTRAINT ck_decision_lobby_choices CHECK ((car_id IS NULL AND lobby_rules_profile IS NULL AND start_type IS NULL AND slipstream IS NULL) OR (car_id IS NOT NULL AND lobby_rules_profile IS NOT NULL AND start_type IS NOT NULL AND slipstream IS NOT NULL AND ((lobby_rules_profile = 'LEGACY' AND start_type = 'GRID_FALSE_START' AND slipstream = 'REAL') OR (lobby_rules_profile = 'CTC_2027' AND CASE start_type WHEN 'GRID_FALSE_START' THEN 1 WHEN 'ROLLING' THEN 1 ELSE 0 END = 1 AND CASE slipstream WHEN 'REAL' THEN 1 WHEN 'WEAK' THEN 1 ELSE 0 END = 1))));
ALTER TABLE pick_publication_attempts DROP CONSTRAINT ck_publication_fields;
ALTER TABLE pick_publication_attempts ADD CONSTRAINT ck_publication_fields CHECK (field_mask >= 0 AND field_mask <= 32767);
